changeSet.sql:
ALTER TABLE practice DROP CONSTRAINT IF EXISTS chk_practice_review_tier;
ALTER TABLE practice_area DROP CONSTRAINT IF EXISTS chk_practice_area_review_tier;
ALTER TABLE workspace DROP CONSTRAINT IF EXISTS chk_workspace_default_review_tier;
DROP INDEX IF EXISTS idx_practice_workspace_tier;

ALTER TABLE practice RENAME COLUMN review_tier TO autonomy;
ALTER TABLE practice_area RENAME COLUMN review_tier TO autonomy;
ALTER TABLE workspace RENAME COLUMN practice_default_review_tier TO practice_default_autonomy;

UPDATE practice SET autonomy = CASE autonomy
    WHEN 'PROPOSE' THEN 'HUMAN_APPROVAL'
    WHEN 'DELIVER' THEN 'AUTOMATIC'
    ELSE autonomy
END;
UPDATE practice_area SET autonomy = CASE autonomy
    WHEN 'PROPOSE' THEN 'HUMAN_APPROVAL'
    WHEN 'DELIVER' THEN 'AUTOMATIC'
    ELSE autonomy
END;
UPDATE workspace SET practice_default_autonomy = CASE practice_default_autonomy
    WHEN 'PROPOSE' THEN 'HUMAN_APPROVAL'
    WHEN 'DELIVER' THEN 'AUTOMATIC'
    ELSE practice_default_autonomy
END;

ALTER TABLE practice ADD CONSTRAINT chk_practice_autonomy
    CHECK (autonomy IS NULL OR autonomy IN ('OFF', 'HUMAN_APPROVAL', 'AUTOMATIC'));
ALTER TABLE practice_area ADD CONSTRAINT chk_practice_area_autonomy
    CHECK (autonomy IS NULL OR autonomy IN ('OFF', 'HUMAN_APPROVAL', 'AUTOMATIC'));
ALTER TABLE workspace ADD CONSTRAINT chk_workspace_default_autonomy
    CHECK (practice_default_autonomy IS NULL OR practice_default_autonomy IN ('OFF', 'HUMAN_APPROVAL', 'AUTOMATIC'));
CREATE INDEX idx_practice_workspace_autonomy ON practice (workspace_id, autonomy);

rollback.sql:
