ALTER TABLE practice_area DROP CONSTRAINT IF EXISTS chk_practice_area_autonomy;
ALTER TABLE workspace DROP CONSTRAINT IF EXISTS chk_workspace_default_autonomy;
DROP INDEX IF EXISTS idx_practice_workspace_autonomy;

UPDATE practice SET autonomy = CASE autonomy WHEN 'HUMAN_APPROVAL' THEN 'PROPOSE' WHEN 'AUTOMATIC' THEN 'DELIVER' ELSE autonomy END;
UPDATE practice_area SET autonomy = CASE autonomy WHEN 'HUMAN_APPROVAL' THEN 'PROPOSE' WHEN 'AUTOMATIC' THEN 'DELIVER' ELSE autonomy END;
UPDATE workspace SET practice_default_autonomy = CASE practice_default_autonomy WHEN 'HUMAN_APPROVAL' THEN 'PROPOSE' WHEN 'AUTOMATIC' THEN 'DELIVER' ELSE practice_default_autonomy END;

ALTER TABLE practice RENAME COLUMN autonomy TO review_tier;
ALTER TABLE practice_area RENAME COLUMN autonomy TO review_tier;
ALTER TABLE workspace RENAME COLUMN practice_default_autonomy TO practice_default_review_tier;
ALTER TABLE practice ADD CONSTRAINT chk_practice_review_tier CHECK (review_tier IS NULL OR review_tier IN ('OFF', 'PROPOSE', 'DELIVER'));
ALTER TABLE practice_area ADD CONSTRAINT chk_practice_area_review_tier CHECK (review_tier IS NULL OR review_tier IN ('OFF', 'PROPOSE', 'DELIVER'));
ALTER TABLE workspace ADD CONSTRAINT chk_workspace_default_review_tier CHECK (practice_default_review_tier IS NULL OR practice_default_review_tier IN ('OFF', 'PROPOSE', 'DELIVER'));
CREATE INDEX idx_practice_workspace_tier ON practice (workspace_id, review_tier);

changeSet.sql:
ALTER TABLE feedback ALTER COLUMN delivery_state TYPE VARCHAR(32);
ALTER TABLE feedback DROP CONSTRAINT chk_feedback_state;
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_state CHECK (delivery_state IN ('AWAITING_APPROVAL', 'PREPARED', 'DELIVERED', 'DISCARDED', 'SUPERSEDED', 'SUPPRESSED', 'FAILED'));
ALTER TABLE feedback DROP CONSTRAINT chk_feedback_suppression_reason;
UPDATE feedback SET suppression_reason = 'PRACTICE_REQUIRES_APPROVAL'
    WHERE suppression_reason = 'PRACTICE_TIER_QUIET';
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_suppression_reason
    CHECK (suppression_reason IS NULL OR suppression_reason IN (
        'VOLUME_CAPPED', 'COMPOSER_DEDUPED', 'REACTED_DISPUTED', 'REACTED_NOT_APPLICABLE',
        'CONVERSATION_EXPIRED', 'ARTIFACT_GONE', 'ARTIFACT_CLOSED', 'ARTIFACT_MERGED',
        'ARTIFACT_DRAFT', 'RECIPIENT_OPTED_OUT', 'EMPTY_AFTER_SANITIZE', 'INSTANCE_SILENCED',
        'PRACTICE_REQUIRES_APPROVAL', 'BACKFILL_QUIET', 'WORKSPACE_DISABLED', 'APPROVAL_STALE',
        'APPROVAL_NO_LONGER_ELIGIBLE'));

ALTER TABLE feedback_approval ADD CONSTRAINT ck_feedback_approval_decision
    CHECK (decision IN ('APPROVED', 'REJECTED'));
ALTER TABLE feedback_approval ADD CONSTRAINT ck_feedback_approval_reason
    CHECK ((decision = 'APPROVED' AND rejection_reason IS NULL) OR
           (decision = 'REJECTED' AND (rejection_reason IS NULL OR rejection_reason IN ('INCORRECT', 'MISSING_CONTEXT', 'UNHELPFUL', 'DUPLICATE', 'INAPPROPRIATE_PLACEMENT', 'OTHER'))));
ALTER TABLE feedback_approval ADD CONSTRAINT ck_feedback_approval_digest
    CHECK (content_digest ~ '^[0-9a-f]{64}$');

rollback.sql:
DELETE FROM feedback WHERE delivery_state IN ('AWAITING_APPROVAL', 'DISCARDED');
UPDATE feedback SET delivery_state = 'FAILED', suppression_reason = NULL
    WHERE suppression_reason IN ('WORKSPACE_DISABLED', 'APPROVAL_STALE', 'APPROVAL_NO_LONGER_ELIGIBLE');
ALTER TABLE feedback DROP CONSTRAINT chk_feedback_state;
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_state CHECK (delivery_state IN ('PREPARED', 'DELIVERED', 'SUPERSEDED', 'SUPPRESSED', 'FAILED'));
ALTER TABLE feedback ALTER COLUMN delivery_state TYPE VARCHAR(16);
ALTER TABLE feedback DROP CONSTRAINT chk_feedback_suppression_reason;
UPDATE feedback SET suppression_reason = 'PRACTICE_TIER_QUIET'
    WHERE suppression_reason = 'PRACTICE_REQUIRES_APPROVAL';
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_suppression_reason
    CHECK (suppression_reason IS NULL OR suppression_reason IN (
        'VOLUME_CAPPED', 'COMPOSER_DEDUPED', 'REACTED_DISPUTED', 'REACTED_NOT_APPLICABLE',
        'CONVERSATION_EXPIRED', 'ARTIFACT_GONE', 'ARTIFACT_CLOSED', 'ARTIFACT_MERGED',
        'ARTIFACT_DRAFT', 'RECIPIENT_OPTED_OUT', 'EMPTY_AFTER_SANITIZE', 'INSTANCE_SILENCED',
        'PRACTICE_TIER_QUIET', 'BACKFILL_QUIET'));
